#!/usr/bin/env bash
# Question 1: Migrate an Ingress to Gateway API. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
rm -rf /opt/course/tls/${Q1_NS}
mkdir -p /opt/course/tls/${Q1_NS}
chown -R ubuntu:ubuntu /opt/course
mkdir -p /root/.cka-tls-${Q1_NS}
openssl req -x509 -newkey rsa:2048 -nodes -days 30 -subj "/CN=shop.${Q1_NS}.lab" -addext "subjectAltName=DNS:shop.${Q1_NS}.lab" -keyout /root/.cka-tls-${Q1_NS}/tls.key -out /root/.cka-tls-${Q1_NS}/tls.crt 2>/dev/null
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" create deployment web --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q1_NS}" expose deployment web --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
  namespace: ${Q1_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: api }
  template:
    metadata:
      labels: { app: api }
    spec:
      containers:
        - name: api
          image: busybox:1.36
          command: ["sh", "-c", "mkdir -p /www/api && echo shop-api > /www/index.html && echo shop-api > /www/api/index.html && httpd -f -p 80 -h /www"]
---
apiVersion: v1
kind: Service
metadata:
  name: api
  namespace: ${Q1_NS}
spec:
  selector: { app: api }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q1_NS}" delete gateway shop-gw --ignore-not-found >/dev/null 2>&1 || true
kubectl -n "${Q1_NS}" create secret tls shop-tls --cert=/root/.cka-tls-${Q1_NS}/tls.crt --key=/root/.cka-tls-${Q1_NS}/tls.key --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: shop
  namespace: ${Q1_NS}
spec:
  ingressClassName: traefik
  tls:
    - hosts: [shop.${Q1_NS}.lab]
      secretName: shop-tls
  rules:
    - host: shop.${Q1_NS}.lab
      http:
        paths:
          - path: /api
            pathType: Prefix
            backend: { service: { name: api, port: { number: 80 } } }
          - path: /
            pathType: Prefix
            backend: { service: { name: web, port: { number: 80 } } }
EOF
kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=180s >/dev/null
kubectl -n "${Q1_NS}" rollout status deployment/api --timeout=180s >/dev/null
: "${Q1_NS}"
